import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = [x - 1 for x in data[2:]]

    children = [[] for _ in range(n)]
    indeg = [0] * n
    for i, p in enumerate(a):
        children[p].append(i)
        indeg[p] += 1

    queue = [i for i in range(n) if indeg[i] == 0]
    removed_order = []
    for u in queue:
        removed_order.append(u)
        p = a[u]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    is_cycle = [x > 0 for x in indeg]
    ways = [None] * n

    # Process tree vertices from leaves towards the cycles.
    for u in removed_order:
        arr = [1] * m
        for c in children[u]:
            fc = ways[c]
            prefix = 0
            for v in range(m):
                prefix += fc[v]
                if prefix >= MOD:
                    prefix -= MOD
                arr[v] = arr[v] * prefix % MOD
        ways[u] = arr

    answer = 1
    seen = [False] * n
    for start in range(n):
        if is_cycle[start] and not seen[start]:
            cycle = []
            u = start
            while not seen[u]:
                seen[u] = True
                cycle.append(u)
                u = a[u]

            component = [1] * m
            for r in cycle:
                for c in children[r]:
                    if not is_cycle[c]:
                        fc = ways[c]
                        prefix = 0
                        for v in range(m):
                            prefix += fc[v]
                            if prefix >= MOD:
                                prefix -= MOD
                            component[v] = component[v] * prefix % MOD
            answer = answer * (sum(component) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

