import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    limit = max(a)

    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for x in range(p, limit + 1, p):
                phi[x] -= phi[x] // p

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    weighted = [0] * (limit + 1)
    answer = 0
    power = 1
    output = []

    for value in a:
        divisors = [1]
        x = value
        while x > 1:
            p = spf[x]
            exponent = 0
            while x % p == 0:
                x //= p
                exponent += 1
            previous = divisors[:]
            multiple = 1
            for _ in range(exponent):
                multiple *= p
                divisors.extend(d * multiple for d in previous)

        added = 0
        for d in divisors:
            added += phi[d] * weighted[d]
        answer = (2 * answer + added) % MOD
        output.append(str(answer))

        for d in divisors:
            weighted[d] = (weighted[d] + power) % MOD
        power = power * 2 % MOD

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    main()

