class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        C = [[0]*(L+1) for _ in range(L+1)]
        C[0][0] = 1
        for i in range(1, L+1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        good = [False]*(L+1)
        for c in range(1, L+1):
            x = c
            for _ in range(k-1):
                if x == 1:
                    break
                x = x.bit_count()
            good[c] = (x == 1)
        ans = 0
        used = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L-i-1
                for c in range(1, L+1):
                    if good[c] and c >= used:
                        need = c-used
                        if 0 <= need <= rem:
                            ans += C[rem][need]
                used += 1
        return ans % MOD

