 def countKReducibleNumbers(self,s,k):
  MOD=10**9+7;L=len(s);C=[[0]*(L+1) for _ in range(L+1)];C[0][0]=1
  for i in range(1,L+1):
   C[i][0]=C[i][i]=1
   for j in range(1,i):C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
  good=[False]*(L+1)
  for c in range(1,L+1):
   x=c
   for _ in range(k-1):
    if x==1:break
    x=x.bit_count()
   good[c]=x==1
  ans=used=0
  for i,ch in enumerate(s):
   if ch=='1':
    rem=L-i-1
    for c in range(1,L+1):
     if good[c] and c>=used and c-used<=rem:ans+=C[rem][c-used]
    used+=1
  return ans%MOD
st=time.time(); print(Solution().countKReducibleNumbers('1'*800,5),time.time()-st)

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # Binomial coefficients count ways to fill the suffix with a
        # specified number of set bits.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        comb[0][0] = 1
        for i in range(1, length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # After the first operation, a number with c set bits becomes c.
        # Thus c must reach 1 in at most k-1 further operations.
        good = [False] * (length + 1)
        for c in range(1, length + 1):
            value = c
            for _ in range(k - 1):
                if value == 1:
                    break
                value = value.bit_count()
            good[c] = (value == 1)

        answer = 0
        used = 0
        for pos, bit in enumerate(s):
            if bit == '1':
                remaining = length - pos - 1
                # Put zero here (making the candidate smaller), then fill
                # the suffix to obtain each possible total popcount.
                for total in range(1, length + 1):
                    need = total - used
                    if good[total] and 0 <= need <= remaining:
                        answer += comb[remaining][need]
                used += 1

        return answer % MOD

