import sys, heapq

def solve():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    g = [x.decode() for x in data[1:]]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    edges = 0
    for i in range(n):
        row = g[i]
        for j, c in enumerate(row):
            if c != '-':
                edges += 1
                k = ord(c) - 97
                out[i][k].append(j)
                inc[j][k].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
    for i in range(n):
        for j, c in enumerate(g[i]):
            if c != '-':
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    complete = (edges == n * n)
    while heap:
        d, u, v = heapq.heappop(heap)
        if d != dist[u][v]:
            continue
        # If every pair has a direct edge, all non-diagonal answers are 1.
        if complete and d >= 1:
            continue
        nd = d + 2
        for k in range(26):
            for a in inc[u][k]:
                row = dist[a]
                for b in out[v][k]:
                    if nd < row[b]:
                        row[b] = nd
                        heapq.heappush(heap, (nd, a, b))

    sys.stdout.write('\n'.join(' '.join(str(x if x < inf else -1) for x in row)
                               for row in dist))

if __name__ == '__main__':
    solve()

