import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    U = vals[::2]
    D = vals[1::2]

    def feasible(h):
        lo = max(0, h - D[0])
        hi = U[0]
        if lo > hi:
            return False
        for i in range(1, n):
            lo = max(0, h - D[i], lo - x)
            hi = min(U[i], hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    high = min(u + d for u, d in zip(U, D)) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(sum(U) + sum(D) - n * low)

if __name__ == "__main__":
    main()

