import sys

def main():
    z=list(map(int,sys.stdin.buffer.read().split()))
    n=z[0]; A=z[1:]
    LIM=(1<<100)-A[-1]-1
    ans=0
    # state: bit position, residue, unresolved (divisible so far), pending (just became odd)
    def dfs(b,r,un,pnd,score):
        nonlocal ans
        if b>=101:
            if pnd:
                return
            if 1<=r<=LIM: ans=max(ans,score)
            return
        for bit in (0,1):
            rr=r|(bit<<b)
            sc=score
            # pending valuations are decided by the current bit of x+A
            for i in pnd:
                if (((rr+A[i])>>b)&1)==0: sc+=1
            np=[]
            nu=[]
            for i in un:
                if (((rr+A[i])>>b)&1)==0:
                    nu.append(i)
                else:
                    np.append(i)
            # if no unresolved, next level resolves pending and then all fixed
            if not nu and not np:
                # score is already complete; lift residue if possible
                if 1<=rr<=LIM or rr==0 and LIM>=1:
                    ans=max(ans,sc)
                continue
            dfs(b+1,rr,nu,np,sc)
    dfs(0,0,list(range(n)),[],0)
    print(ans)
