class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        pw = [1] * n
        for i in range(1, n):
            pw[i] = (pw[i - 1] * 10) % k

        coeff = []
        for j in range(m):
            if j == n - 1 - j:
                coeff.append(pw[j])
            else:
                coeff.append((pw[j] + pw[n - 1 - j]) % k)

        # suf[i] is the set of residues obtainable by positions i onward.
        suf = [0] * (m + 1)
        suf[m] = 1
        for i in range(m - 1, -1, -1):
            old = suf[i + 1]
            c = coeff[i]
            mask = 0
            for d in range(10):
                shift = (d * c) % k
                for r in range(k):
                    if old & (1 << r):
                        mask |= 1 << ((r + shift) % k)
            suf[i] = mask

        rem = 0
        left = []
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                needed = (-(rem + d * c)) % k
                if suf[i + 1] & (1 << needed):
                    left.append(str(d))
                    rem = (rem + d * c) % k
                    break

        prefix = ''.join(left)
        return prefix + prefix[:n // 2][::-1]

