from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        base = [nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
                for i in range(n)]
        levels_next = [nxt]
        levels_cost = [base]
        levels = n.bit_length()
        for _ in range(1, levels):
            old_next = levels_next[-1]
            old_cost = levels_cost[-1]
            new_next = [0] * n
            new_cost = [0] * n
            for i in range(n):
                q = old_next[i]
                if q < n:
                    new_next[i] = old_next[q]
                    new_cost[i] = old_cost[i] + old_cost[q]
                else:
                    new_next[i] = n
                    new_cost[i] = old_cost[i]
            levels_next.append(new_next)
            levels_cost.append(new_cost)

        def required(left, right):
            total = 0
            for level in range(levels - 1, -1, -1):
                endpoint = levels_next[level][left]
                if endpoint <= right:
                    total += levels_cost[level][left]
                    left = endpoint
            return total + nums[left] * (right - left + 1) - (pref[right + 1] - pref[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if required(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

