import sys
from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, 2 * n + 2, 2)]

    # For two functions f=(a,b), g=(c,d), f should be outer to g iff
    # (a-1)*d <= (c-1)*b.  Thus sort by (a-1)/b increasingly.
    def compare(x, y):
        cross = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
        if cross < 0:
            return -1
        if cross > 0:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))

    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(k, 0, -1):
            candidate = a * dp[count - 1] + b
            if candidate > dp[count]:
                dp[count] = candidate

    print(dp[k])


if __name__ == "__main__":
    main()

