class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        table = [array('I', [0]) * n for _ in range(n)]

        for i, value in enumerate(nums):
            table[i][i] = value

        # First compute the XOR score of every subarray.
        for length in range(2, n + 1):
            for left in range(n - length + 1):
                right = left + length - 1
                table[left][right] = (table[left + 1][right] ^
                                       table[left][right - 1])

        # Turn each entry into the maximum score contained in that interval.
        for length in range(2, n + 1):
            for left in range(n - length + 1):
                right = left + length - 1
                best = table[left][right]
                if table[left + 1][right] > best:
                    best = table[left + 1][right]
                if table[left][right - 1] > best:
                    best = table[left][right - 1]
                table[left][right] = best

        return [table[left][right] for left, right in queries]

