import sys
from functools import lru_cache

sys.setrecursionlimit(1000000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    k = n + m + l
    pow3 = [3 ** i for i in range(k)]
    initial = sum(pow3[:n]) + 2 * sum(pow3[n:n + m])

    @lru_cache(maxsize=None)
    def winning(state, turn):
        owner = turn + 1
        for i, value in enumerate(values):
            pi = pow3[i]
            if state // pi % 3 != owner:
                continue
            # Play this card, without taking another card.
            after_play = state - owner * pi
            if not winning(after_play, 1 - turn):
                return True
            # Take any lower-valued card currently on the table.
            for j, other in enumerate(values):
                pj = pow3[j]
                if other < value and after_play // pj % 3 == 0:
                    after_take = after_play + owner * pj
                    if not winning(after_take, 1 - turn):
                        return True
        return False

    print("Takahashi" if winning(initial, 0) else "Aoki")

if __name__ == "__main__":
    main()

