from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def occurrences(word):
            if not word:
                return None
            m = len(word)
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        lists = [occurrences(x) for x in (first, middle, last)]
        la, lm, ll = len(first), len(middle), len(last)
        starts = range(n + 1) if lists[0] is None else lists[0]
        best = n + 1

        for start in starts:
            need = start + la
            if lists[1] is None:
                mid = need if need <= n else -1
            else:
                q = bisect_left(lists[1], need)
                mid = lists[1][q] if q < len(lists[1]) else -1
            if mid < 0:
                continue
            need = mid + lm
            if lists[2] is None:
                end = need if need <= n else -1
            else:
                q = bisect_left(lists[2], need)
                end = lists[2][q] if q < len(lists[2]) else -1
            if end >= 0:
                best = min(best, end + ll - start)
        return -1 if best == n + 1 else best

