MOD=998244353

def solve(s):
    # dp[x]: partial matchings leaving x earlier black vertices unmatched
    dp={0:1}
    nb=nw=0
    last=len(s)-1
    for i,c in enumerate(s):
        nd={}
        if c=='B':
            delta=nb-nw
            for x,v in dp.items():
                y=x-delta
                nd[x]=(nd.get(x,0)+v*y)%MOD
                nd[x+1]=(nd.get(x+1,0)+v)%MOD
            nb+=1
        else:
            for x,v in dp.items():
                nd[x]=(nd.get(x,0)+v)%MOD
                if x:
                    nd[x-1]=(nd.get(x-1,0)+v*x)%MOD
            nw+=1
        if i!=last:
            nd.pop(0,None)
        dp=nd
    return dp.get(0,0)%MOD

