def main():
    n = int(sys.stdin.buffer.readline())
    limit = math.isqrt(n)

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, math.isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * (((limit - start) // p) + 1)

    primes = [i for i in range(2, limit + 1) if sieve[i]]

    # Numbers of the form p^2 q^2, where p and q are distinct primes.
    answer = 0
    for i, p in enumerate(primes):
        if p * p > limit:
            break
        answer += bisect.bisect_right(primes, limit // p) - i - 1

    # Numbers of the form p^8.
    for p in primes:
        if p ** 8 <= n:
            answer += 1
        else:
            break

    print(answer)


