from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # A state i contributes the line
        # dp[i] + (x-i)*nums[i] = nums[i]*x + dp[i]-i*nums[i].
        # Li Chao tree stores the maximum of these lines.
        m = n - 1
        tree = [None] * (4 * m)

        def value(line, x):
            return line[0] * x + line[1]

        def insert(line, p, left, right):
            current = tree[p]
            if current is None:
                tree[p] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                tree[p], line = line, current
            if left == right:
                return
            if value(line, left) > value(tree[p], left):
                insert(line, p * 2, left, mid)
            elif value(line, right) > value(tree[p], right):
                insert(line, p * 2 + 1, mid + 1, right)

        def query(x, p, left, right):
            line = tree[p]
            result = value(line, x) if line is not None else -10**30
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
                return max(result, query(x, p * 2, left, mid))
            return max(result, query(x, p * 2 + 1, mid + 1, right))

        insert((nums[0], 0), 1, 1, m)
        answer = 0
        for j in range(1, n):
            answer = query(j, 1, 1, m)
            if j < m:
                insert((nums[j], answer - j * nums[j]), 1, 1, m)
        return answer

