class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 0 if digits == 1 else 10 ** (digits - 1)
        high = 10 ** digits - 1

        prime = [True] * (high + 1)
        prime[0] = False
        if high >= 1:
            prime[1] = False
        for i in range(2, int(high ** 0.5) + 1):
            if prime[i]:
                for j in range(i * i, high + 1, i):
                    prime[j] = False

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        heap = [(n, n)]
        limit = 10 ** digits
        while heap:
