from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # While moving i right-to-left, lcp[j] stores LCP(i, j).
        # The old value at j+1 is LCP(i+1, j+1), so one row is enough.
        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    lcp[j] = 1 + lcp[j + 1]
                else:
                    lcp[j] = 0
                first_is_prefix = j - i >= i and z[i] >= i
                second_is_prefix = lcp[j] >= j - i
                if first_is_prefix or second_is_prefix:
                    answer += 1
        return answer

