from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        targets = set(targetIndices)
        inf = 10**9
        # dp[j] is the minimum number of target characters needed to
        # match pattern[:j] among the source characters processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if i in targets else 0
            # Descending order ensures each source character is used once.
            for j in range(m, 0, -1):
                if ch == pattern[j - 1]:
                    candidate = dp[j - 1] + cost
                    if candidate < dp[j]:
                        dp[j] = candidate

        return len(targetIndices) - dp[m]

